// CrowdRelay decided WHICH city needs venues and HOW MANY to find.
// This workflow reads published booking/contact routes and reports them.
// It never contacts anyone — screening happens on ingest in CrowdRelay.
const e = $json;
if (!e || e.type !== 'viryaos.booking.target_discovery_requested' || e.version !== 1) return [];
const d = e.data ?? {};
if (!d.requested_count || !Number.isInteger(d.requested_count)) throw new Error('missing requested_count');
return [{ json: {
  action_id: String(d.action_id || ''),
  requested_count: d.requested_count,
  screening: d.screening_contract ?? {},
}}];
